import os
import requests

def compare_metric_series(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.getenv("DD_API_KEY")
    app_key = config.get("app_key") or os.getenv("DD_APP_KEY")
    base_url = config.get("base_url", "https://api.datadoghq.com")

    headers = {
        "Accept": "application/json",
        "DD-API-KEY": api_key,
        "DD-APPLICATION-KEY": app_key
    }
    params = {
        "from": payload.get("start"),
        "to": payload.get("end"),
        "query": ",".join(payload.get("queries", []))
    }
    response = requests.get(f"{base_url}/api/v1/query", headers=headers, params=params)
    response.raise_for_status()
    raw_series = response.json().get("series", [])

    result = {
        "window": {"start": payload.get("start"), "end": payload.get("end")},
        "comparison": [
            {
                "resource_or_filter": s.get("scope", s.get("metric")),
                "point_count": len(s.get("pointlist", [])),
                "average_value": sum(p[1] for p in s.get("pointlist", [])) / max(len(s.get("pointlist", [])), 1),
                "latest_value": s.get("pointlist", [])[-1][1] if s.get("pointlist") else None
            }
            for s in raw_series
        ]
    }
    return result
